:root {
  color-scheme: light;
  --ink: #233344;
  --muted: #687887;
  --paper: #fffdf7;
  --line: #d8e0d9;
  --mint: #b8e3d2;
  --mint-dark: #397c69;
  --orange: #f3a65a;
  --red: #b34d4d;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #e9f0e6;
  background-image: linear-gradient(45deg, #dce8dc 25%, transparent 25%), linear-gradient(-45deg, #dce8dc 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #dce8dc 75%), linear-gradient(-45deg, transparent 75%, #dce8dc 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
  color: var(--ink);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
}

.calculator {
  width: min(100%, 440px);
  padding: 28px;
  border: 3px solid var(--ink);
  border-radius: 12px;
  background: var(--paper);
  box-shadow: 8px 8px 0 var(--ink);
}

.eyebrow { margin: 0 0 6px; color: var(--mint-dark); font-size: 16px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(32px, 9vw, 42px); line-height: 1.1; }
.subtitle { margin: 8px 0 24px; color: var(--muted); }

.stack-panel { padding: 16px; border: 2px solid var(--ink); border-radius: 8px; background: #f3f7f1; }
.panel-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 18px; }
.stack-count { color: var(--muted); font-size: 16px; }
.stack { display: flex; flex-direction: column-reverse; gap: 8px; min-height: 90px; max-height: 190px; margin: 12px 0 0; padding: 0; overflow-y: auto; list-style: none; }
.stack li { display: flex; align-items: center; justify-content: space-between; min-height: 44px; padding: 8px 12px; border: 1px solid var(--line); border-radius: 6px; background: white; font-variant-numeric: tabular-nums; }
.stack li:first-child:not(.empty-state) { border-color: var(--mint-dark); background: #e1f3eb; font-weight: 750; }
.stack .empty-state { justify-content: center; border-style: dashed; color: var(--muted); }
.stack-index { color: var(--muted); font-size: 14px; }

.error { margin: 12px 0 0; padding: 10px 12px; border: 1px solid var(--red); border-radius: 6px; background: #fff0ed; color: #8b3333; }
[hidden] { display: none !important; }

.keypad { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; margin-top: 18px; }
.key { min-height: 56px; border: 2px solid var(--ink); border-radius: 7px; background: white; color: var(--ink); font: inherit; font-size: 20px; font-weight: 750; cursor: pointer; box-shadow: 0 3px 0 var(--ink); transition: transform .08s ease, box-shadow .08s ease, background-color .12s ease; }
.key:hover { background: #f0f6ef; }
.key:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
.key:active { transform: translateY(3px); box-shadow: 0 0 0 var(--ink); }
.operation { background: var(--mint); }
.operation:hover { background: #a5d9c4; }
.enter { background: var(--orange); }
.enter:hover { background: #f6b974; }
.clear { grid-column: 1 / -1; min-height: 50px; background: var(--ink); color: white; }
.clear:hover { background: #344c60; }
.hint { margin: 18px 0 0; color: var(--muted); font-size: 14px; line-height: 1.6; }
kbd { padding: 1px 5px; border: 1px solid var(--line); border-radius: 4px; background: white; color: var(--ink); font: inherit; }

@media (max-width: 400px) {
  body { padding: 20px 14px; }
  .calculator { padding: 20px; box-shadow: 5px 5px 0 var(--ink); }
  .keypad { gap: 8px; }
  .key { min-height: 52px; }
}

const stack = [];
let entry = '';
const stackEl = document.querySelector('#stack');
const countEl = document.querySelector('#stack-count');
const errorEl = document.querySelector('#error');

function showError(message) {
  errorEl.textContent = message;
  errorEl.hidden = false;
}

function clearError() {
  errorEl.textContent = '';
  errorEl.hidden = true;
}

function render() {
  stackEl.replaceChildren();
  if (!stack.length) {
    const empty = document.createElement('li');
    empty.className = 'empty-state';
    empty.textContent = entry ? `Typing: ${entry}` : 'Your stack is empty';
    stackEl.append(empty);
  } else {
    stack.forEach((value, index) => {
      const item = document.createElement('li');
      const number = document.createElement('span');
      const label = document.createElement('span');
      number.textContent = format(value);
      label.className = 'stack-index';
      label.textContent = index === stack.length - 1 ? 'TOP' : `#${index + 1}`;
      item.append(number, label);
      stackEl.append(item);
    });
  }
  countEl.textContent = `${stack.length} ${stack.length === 1 ? 'value' : 'values'}`;
}

function format(value) {
  return Number.isInteger(value) ? String(value) : String(Number(value.toPrecision(10)));
}

function digit(value) {
  clearError();
  if (value === '.' && entry.includes('.')) return;
  entry += value;
  render();
}

function push() {
  if (!entry || entry === '.') {
    showError('Enter a number before pushing it.');
    return;
  }
  const value = Number(entry);
  if (!Number.isFinite(value)) {
    showError('That number is out of range.');
    return;
  }
  stack.push(value);
  entry = '';
  clearError();
  render();
}

function operate(operator) {
  if (entry) push();
  if (stack.length < 2) {
    showError('This operation needs two values on the stack.');
    return;
  }
  const right = stack.pop();
  const left = stack.pop();
  const result = operator === '+' ? left + right
    : operator === '−' ? left - right
      : operator === '×' ? left * right
        : left / right;
  if (!Number.isFinite(result)) {
    stack.push(left, right);
    showError('Result is out of range.');
    render();
    return;
  }
  stack.push(result);
  clearError();
  render();
}

function clear() {
  stack.length = 0;
  entry = '';
  clearError();
  render();
}

document.querySelectorAll('[data-digit]').forEach(button => {
  button.addEventListener('click', () => digit(button.dataset.digit));
});
document.querySelectorAll('[data-op]').forEach(button => {
  button.addEventListener('click', () => operate(button.dataset.op));
});
document.querySelector('#enter').addEventListener('click', push);
document.querySelector('#clear').addEventListener('click', clear);

document.addEventListener('keydown', event => {
  if (/^[0-9.]$/.test(event.key)) digit(event.key);
  else if (event.key === 'Enter') { event.preventDefault(); push(); }
  else if (event.key === '+') operate('+');
  else if (event.key === '-') operate('−');
  else if (event.key === '*') operate('×');
  else if (event.key === '/') operate('÷');
  else if (event.key === 'Escape') clear();
});

render();
